import React from 'react';
import { Link } from 'react-router-dom';

interface User {
  id: string;
  name: string;
  role: string;
  email: string;
}

interface SidebarProps {
  user: User;
  onLogout: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ user, onLogout }) => {
  return (
    <aside className="sidebar">
      <div className="sidebar-header">
        <h3>Mr. Rideo Admin</h3>
      </div>

      <nav className="sidebar-nav">
        <Link to="/dashboard" className="nav-item" onClick={() => window.location.href = '/dashboard'}>
          <span className="nav-icon">🏠</span>
          Dashboard
        </Link>
        <Link to="/kyc" className="nav-item" onClick={() => window.location.href = '/kyc'}>
          <span className="nav-icon">👥</span>
          KYC Management
        </Link>
        <Link to="/payments" className="nav-item" onClick={() => window.location.href = '/payments'}>
          <span className="nav-icon">💰</span>
          Payments
        </Link>
        <Link to="/trips" className="nav-item" onClick={() => window.location.href = '/trips'}>
          <span className="nav-icon">🚗</span>
          Trip Reports
        </Link>
        <Link to="/logout" className="nav-item" onClick={onLogout}>
          <span className="nav-icon">🚪</span>
          Logout
        </Link>
      </nav>
    </aside>
  );
}

export default Sidebar;
